def _parse_money(value: str) -> Decimal:
    """The dollar amount on a line, ignoring quantities in trailing notes."""
    money = _MONEY.search(value)
    if money:
        return Decimal(money.group(1).replace(",", ""))
    number = _NUMBER.search(value)
    if not number:
        raise RateConError(f"no amount in {value!r}")
    # The amount comes first; trailing notes may contain other numbers
    # ("$100.00 (1 extra stop)", "$75.00/hr after 2 hrs free").
    return Decimal(number.group(0).replace(",", ""))

